", "authorHandle": "@37771504551", "canonicalUrl": "https://www.iesdouyin.com/share/video/7659470701799214374/?region=CN&mid=7659470926295157546&u_code=-1&did=MS4wLjABAAAAxxv9qeA5GRrY4Nh_P9hMzgzauCRCqgesZ8D0V8ZRUqxXjxoxy0zCa6RtCwBYO5IX&iid=MS4wLjABAAAANwkJuWIRFOzg5uCpDRpMj4OX-QryoDgn-yYlXQnRwQQ&with_sec_did=1&video_share_track_ver=&titleType=title&share_sign=awh_HOARGVE02r8uHBmDpgkzlyPr_6ivKqi9BPM3lKM-&share_version=270000&ts=1784024577&from_aid=1128&from_ssr=1&share_track_info=%7B%22link_description_type%22%3A%22%22%7D"}	movie_recap	ready	remix_draft	{"locale": "vi", "script": {"sections": [{"text": "Câu chuyện bắt đầu tại một thị trấn nhỏ, nơi một kẻ phản diện đang thống trị và khiến cuộc sống của mọi người trở nên khổ cực.", "label": "Mở đầu"}, {"text": "Hai nhân vật chính, một lão cao bồi và một người trẻ tuổi đầy nhiệt huyết, quyết định đứng lên chống lại sự đàn áp này.", "label": "Nhân vật chính"}, {"text": "Những cuộc đối đầu nảy lửa diễn ra, tạo nên những khoảnh khắc căng thẳng và nghẹt thở, cho thấy lòng dũng cảm và tình bạn giữa hai người họ.", "label": "Cuộc chiến"}, {"text": "Cuối cùng, một cuộc đối đầu định mệnh xảy ra, và không ai có thể đoán trước được ai sẽ là người chiến thắng trong trận chiến này.", "label": "Kết thúc"}], "narration": "Chào mừng các bạn đến với câu chuyện của hai cao bồi trong bối cảnh miền Tây nước Mỹ, nơi mà những mâu thuẫn và quyết đấu không bao giờ ngừng lại! Hãy cùng khám phá hành trình đầy kịch tính của 'Người Hùng Hoàng Hôn'.", "duration_estimate_sec": 120}, "banners": {"top": "Phiêu lưu miền Tây", "bottom": "Câu chuyện của những anh hùng", "watermark": "Classic Movie Recap"}, "hook_3s": {"spoken": "Xem ngay câu chuyện kịch tính của hai cao bồi!", "on_screen": "Hành trình của những kẻ hùng mạnh!", "visual_hint": "Cao bồi trong ánh hoàng hôn"}, "packaging": {"titles": ["Người Hùng Hoàng Hôn"], "hashtags": ["#NgườiHùngHoàngHôn", "#CaoBồi", "#PhimCổĐiển"], "description": "Một cuộc chiến ganh đua và lòng dũng cảm giữa hai cao bồi trong bối cảnh hỗn loạn của miền Tây nước Mỹ."}, "subtitles": {"cues": [{"end": "00:00:05,000", "text": "Chào mừng các bạn đến với câu chuyện của hai cao bồi!", "start": "00:00:00,000"}, {"end": "00:00:10,000", "text": "Bối cảnh miền Tây, nơi những kẻ chống đối không bao giờ tạm dừng.", "start": "00:00:05,000"}, {"end": "00:00:15,000", "text": "Hành trình của hai nhân vật chính bắt đầu từ đây.", "start": "00:00:10,000"}, {"end": "00:00:20,000", "text": "Những cuộc đối đầu căng thẳng diễn ra khắp nơi.", "start": "00:00:15,000"}, {"end": "00:00:25,000", "text": "Liệu tình bạn và lòng dũng cảm sẽ chiến thắng?", "start": "00:00:20,000"}], "format": "srt"}, "transform_notes": {"risks": ["Có thể không truyền tải được hết tinh thần nguyên bản", "Nguy cơ bị hiểu lầm nội dung"], "source_language": "zh", "rewrite_strategy": "Sáng tạo nội dung mới trên cơ sở cảm hứng"}}	{"hookIsNew": false, "leadApproved": false, "hasStudioBrand": false, "noFullReupload": false, "scriptRewritten": false, "voiceWillBeRerecorded": false}	{}	\N	\N	\N	514	869	0.0005985	2026-07-14 10:22:50.072	2026-07-14 10:25:40.11	\N	\N	ready	caption	\N	\N	\N	\N
