n diễn ra hoàn toàn khác biệt.", "label": "Giới thiệu"}, {"text": "Thay vì cướp bóc, họ tình cờ đụng phải các hoàn cảnh khó khăn và quyết định giúp đỡ thay vì làm hại người khác.", "label": "Tình huống éo le"}, {"text": "Trong hành trình từ cướp bóc thành từ thiện, họ nhận ra giá trị thực sự của cuộc sống và giúp đỡ những người kém may mắn.", "label": "Bài học ý nghĩa"}, {"text": "Với những tình huống ngớ ngẩn và hài hước, phim khép lại mở ra một cái nhìn mới về lòng tốt và sự sẻ chia.", "label": "Kết thúc hài hước"}], "narration": "Một bộ phim hài kịch thú vị khi tình huống không như mong đợi. Những tên cướp dự định đi ăn cướp nhưng lại bất đắc dĩ trở thành những người hùng trong công cuộc từ thiện. Họ đã phải đối mặt với những sự kiện dở khóc dở cười, mang lại những bài học và những giây phút hài hước cho khán giả.", "duration_estimate_sec": 45}, "banners": {"top": "Bộ phim hài kịch thú vị", "bottom": "Giúp đỡ thay vì cướp bóc!", "watermark": "Video recap phim"}, "hook_3s": {"spoken": "Cướp nhưng lại thành từ thiện?!", "on_screen": "Một cuộc phiêu lưu bất ngờ", "visual_hint": "Hình ảnh những tên cướp bối rối"}, "packaging": {"titles": ["Hài kịch từ thiện"], "hashtags": ["#phimhài", "#từthiện", "#khámphá"], "description": "Khám phá hành trình hài hước của những tên cướp trở thành người hùng trong việc từ thiện."}, "subtitles": {"cues": [{"end": "00:00:05,000", "text": "Cướp nhưng lại thành từ thiện?!", "start": "00:00:01,000"}, {"end": "00:00:15,000", "text": "Bộ phim bắt đầu với một nhóm cướp có kế hoạch ăn cướp táo bạo.", "start": "00:00:06,000"}, {"end": "00:00:25,000", "text": "Nhưng mọi chuyện diễn ra hoàn toàn khác biệt khi họ gặp những tình huống éo le.", "start": "00:00:16,000"}, {"end": "00:00:35,000", "text": "Thay vì cướp bóc, họ tình cờ quyết định giúp đỡ những người gặp khó khăn.", "start": "00:00:26,000"}, {"end": "00:00:45,000", "text": "Cuối cùng, họ nhận ra giá trị thực sự của lòng tốt và sự sẻ chia.", "start": "00:00:36,000"}], "format": "srt"}, "transform_notes": {"risks": ["Có thể không truyền tải đầy đủ cảm xúc của phim."], "source_language": "zh", "rewrite_strategy": "Tóm tắt nội dung phim với những điểm nhấn hài hước và ý nghĩa."}}	{"hookIsNew": false, "leadApproved": false, "hasStudioBrand": false, "noFullReupload": false, "scriptRewritten": false, "voiceWillBeRerecorded": false}	{}	\N	\N	\N	563	898	0.00062325	2026-07-15 03:42:28.091	2026-07-15 04:04:30.397	\N	\N	ready	caption	\N	\N	\N	\N
