ám Phá Hai Kẻ Đấu Súng Lúc Hoàng Hôn"], "hashtags": ["#PhimCổĐiển", "#PhimHay", "#HaiKeDauSung"], "description": "Cùng theo dõi cuộc chiến không chỉ về súng đạn mà còn về tâm hồn và tình bạn trong bộ phim cổ điển này."}, "subtitles": {"cues": [{"end": "00:00:05,000", "text": "Hãy cùng khám phá một trong những bộ phim cổ điển của Ý.", "start": "00:00:01,000"}, {"end": "00:00:10,000", "text": "Câu chuyện diễn ra tại miền Tây hoang dã.", "start": "00:00:06,000"}, {"end": "00:00:15,000", "text": "Cuộc tranh đấu giữa hai kẻ bắn súng diễn ra đầy kịch tính.", "start": "00:00:11,000"}, {"end": "00:00:20,000", "text": "Kết thúc đẫm nước mắt, bài học về sự hi sinh.", "start": "00:00:16,000"}], "format": "srt"}, "transform_notes": {"risks": ["Có thể làm mất một số chi tiết cụ thể của cốt truyện."], "source_language": "zh", "rewrite_strategy": "Tóm tắt và chuyển đổi theo phong cách kể chuyện"}}	{"hookIsNew": true, "leadApproved": true, "hasStudioBrand": true, "noFullReupload": true, "scriptRewritten": true, "voiceWillBeRerecorded": true}	{}	\N	cmrk3bzxg0000vsr4fzlv4lf7	2026-07-15 02:56:59.755	514	797	0.0005553	2026-07-14 10:26:39.82	2026-07-15 04:04:46.641	\N	\N	ready	caption	\N	\N	\N	\N
